'use client';
import { useEffect, useState } from 'react';
import Link from 'next/link';
import { Alert, Avatar, Box, Button, LinearProgress, Paper, Skeleton, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { ArrowRight, ArrowUpRight, BarChart3, ContactRound, Handshake, Users, Wallet, RefreshCw } from 'lucide-react';
import { buscarIndicadores } from '@/servicos/indicadores';
import { descreverErro } from '@/servicos/api';
import type { ResumoIndicadores } from '@/tipos/indicadores';
import { CartaoIndicador } from './indicadores/CartaoIndicador';
import { coresStatus, formatarMoeda, rotulos, TextoStatus } from './TextoStatus';

export function Painel() {
  const [resumo, definirResumo] = useState<ResumoIndicadores | null>(null);
  const [erro, definirErro] = useState('');
  const [versao, definirVersao] = useState(0);
  useEffect(() => { let ativo = true; buscarIndicadores().then(dados => { if (ativo) { definirResumo(dados); definirErro(''); } }).catch(falha => { if (ativo) definirErro(descreverErro(falha)); }); return () => { ativo = false; }; }, [versao]);
  return <><Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, flexWrap: 'wrap', mb: 3.5 }}><Box><Typography sx={{ color: 'primary.main', fontWeight: 700, fontSize: 10, letterSpacing: 1.7, mb: 1 }}>SEU NEGÓCIO, MAIS PERTO</Typography><Typography variant="h4">Visão geral</Typography><Typography sx={{ color: 'text.secondary', fontSize: 13, mt: 1 }}>Um olhar completo sobre seus relacionamentos e próximos negócios.</Typography></Box><Button component={Link} href="/oportunidades" variant="contained" endIcon={<ArrowUpRight size={17} />} sx={{ alignSelf: 'center' }}>Ver oportunidades</Button></Box>
    {erro && <Alert severity="error" sx={{ mb: 3 }} action={<Button color="inherit" onClick={() => definirVersao(versao + 1)}>Tentar novamente</Button>}>{erro}</Alert>}
    {resumo?.somenteLeitura && <Alert severity="info" sx={{ mb: 3 }}>Demonstração somente leitura. Explore os dados fictícios com segurança.</Alert>}
    {!resumo && !erro ? <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', xl: 'repeat(4,1fr)' }, gap: 2 }}>{[1, 2, 3, 4].map(numero => <Skeleton key={numero} variant="rounded" height={160} />)}</Box> : resumo && <>
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', xl: 'repeat(4,1fr)' }, gap: 2 }}><CartaoIndicador titulo="Total de clientes" valor={resumo.totalClientes} detalhe="Relacionamentos na sua base" icone={Users} cor="#2563EB" /><CartaoIndicador titulo="Leads ativos" valor={resumo.leadsAtivos} detalhe="Novas conexões em desenvolvimento" icone={ContactRound} cor="#8656CA" /><CartaoIndicador titulo="Oportunidades abertas" valor={resumo.oportunidadesAbertas} detalhe="Negócios em andamento" icone={Handshake} cor="#D49B2F" /><CartaoIndicador titulo="Valor das oportunidades" valor={formatarMoeda(resumo.valorTotalCentavos)} detalhe="Valor total de todas as etapas" icone={Wallet} cor="#13876B" /></Box>
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '1.7fr 1fr' }, gap: 2.5, mt: 3 }}><Paper variant="outlined" sx={{ p: 3, borderColor: '#E7EBF1' }}><Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}><Typography variant="h6">Oportunidades por etapa</Typography><BarChart3 size={18} color="#97A1B0" /></Box><Typography sx={{ fontSize: 11, color: 'text.secondary', mb: 3 }}>Acompanhe cada passo do seu processo comercial</Typography><Box role="img" aria-label={`Oportunidades por etapa: ${resumo.oportunidadesPorEtapa.map(item => `${rotulos[item.etapa]}: ${item.quantidade}`).join(', ')}`}>{resumo.oportunidadesPorEtapa.map(item => <Box key={item.etapa} sx={{ display: 'grid', gridTemplateColumns: { xs: '115px 1fr 20px', sm: '135px 1fr 25px' }, gap: 2, alignItems: 'center', mb: 2.5 }}><Typography sx={{ fontSize: 11, color: 'text.secondary' }}>{rotulos[item.etapa]}</Typography><LinearProgress variant="determinate" value={item.quantidade / Math.max(...resumo.oportunidadesPorEtapa.map(etapa => etapa.quantidade), 1) * 100} sx={{ height: 13, borderRadius: 1, bgcolor: '#F3F5F8', '& .MuiLinearProgress-bar': { bgcolor: coresStatus[item.etapa], borderRadius: 1 } }} /><Typography sx={{ fontSize: 12, fontWeight: 700 }}>{item.quantidade}</Typography></Box>)}</Box></Paper>
      <Paper variant="outlined" sx={{ p: 3, borderColor: '#DBE6FD', bgcolor: '#F1F5FF', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}><Box sx={{ bgcolor: '#E1EAFF', color: 'primary.main', p: 1.3, borderRadius: 2, mb: 2.5, display: 'flex' }}><Handshake size={23} /></Box><Typography sx={{ fontSize: 22, fontWeight: 750, lineHeight: 1.3, letterSpacing: '-.5px', maxWidth: 250 }}>O próximo bom negócio começa com uma conexão.</Typography><Typography sx={{ fontSize: 12, lineHeight: 1.9, color: '#62728C', mt: 1.5, mb: 2.5 }}>Mantenha seus leads por perto. Cada conversa é uma nova oportunidade de crescer.</Typography><Button component={Link} href="/leads" endIcon={<ArrowRight size={16} />} sx={{ mt: 'auto', p: 0 }}>Explorar meus leads</Button></Paper></Box>
      <Paper variant="outlined" sx={{ mt: 3, borderColor: '#E7EBF1', overflow: 'hidden' }}><Box sx={{ p: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 1 }}><Box><Typography variant="h6">Últimas conexões</Typography><Typography sx={{ fontSize: 11, color: 'text.secondary', mt: .7 }}>Os leads mais recentes da sua base</Typography></Box><Button component={Link} href="/leads" size="small" endIcon={<ArrowRight size={15} />}>Ver todos</Button></Box><TableContainer><Table aria-label="Últimos leads cadastrados"><TableHead><TableRow>{['Nome', 'Empresa', 'Origem', 'Status', 'Cadastro'].map(titulo => <TableCell key={titulo}>{titulo}</TableCell>)}</TableRow></TableHead><TableBody>{resumo.ultimosLeads.map(lead => <TableRow key={lead.id} hover><TableCell><Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}><Avatar sx={{ bgcolor: '#EDF2FF', color: '#5774B0', width: 33, height: 33, fontSize: 11 }}>{lead.nome.split(' ').map(parte => parte[0]).slice(0, 2).join('')}</Avatar><Box><Typography sx={{ fontSize: 12, fontWeight: 600 }}>{lead.nome}</Typography><Typography sx={{ fontSize: 10, color: 'text.secondary', mt: .4 }}>{lead.email}</Typography></Box></Box></TableCell><TableCell sx={{ fontSize: 12 }}>{lead.empresa}</TableCell><TableCell sx={{ fontSize: 11, color: 'text.secondary' }}>{lead.origem}</TableCell><TableCell><TextoStatus valor={lead.status} /></TableCell><TableCell sx={{ fontSize: 11, color: 'text.secondary' }}>{new Date(lead.criadoEm).toLocaleDateString('pt-BR')}</TableCell></TableRow>)}{!resumo.ultimosLeads.length && <TableRow><TableCell colSpan={5}>Nenhum lead cadastrado. Comece criando sua primeira conexão.</TableCell></TableRow>}</TableBody></Table></TableContainer></Paper><Box sx={{ display: 'flex', alignItems: 'center', gap: .8, mt: 2, color: 'text.secondary' }}><RefreshCw size={11} /><Typography sx={{ fontSize: 10 }}>Indicadores calculados a partir dos dados da API</Typography></Box>
    </>}
  </>;
}
